1	import { access } from "node:fs/promises";
2	import type { IncomingMessage } from "node:http";
3	import type { Duplex } from "node:stream";
4	
5	import { WebSocket, WebSocketServer } from "ws";
6	
7	import type { AgentManager } from "../agents/manager.js";
8	import { RelativizeAbsolutePath } from "../agui/sanitizer.js";
9	import {
10	  ParseClientFrame,
11	  x_clientAckKind,
12	  x_clientCancelKind,
13	  x_clientHelloKind,
14	  x_clientHistoryRequestKind,
15	  x_clientModelSelectKind,
16	  x_clientPingKind,
17	  x_clientStopGeneratingKind,
18	  x_clientUserMessageKind,
19	  ToModelReference,
20	} from "../protocol/clientFrames.js";
21	import {
22	  CreateChatEnvelope,
23	  x_serverCaughtUpKind,
24	  x_serverErrorKind,
25	  x_serverHelloKind,
26	  x_serverPongKind,
27	} from "../protocol/envelopes.js";
28	import {
29	  SessionBroadcasterRegistry,
30	  type ConnectedClient,
31	} from "../protocol/sessionBroadcaster.js";
32	import type { SheafChatConfig } from "./config.js";
33	import { ParseOptionalInteger } from "./http.js";
34	import { ResolveSessionFilePath } from "../storage/paths.js";
35	import { StorageError } from "../storage/errors.js";
36	import { ValidatePileName, ValidateSessionId } from "../storage/validation.js";
37	
38	export interface ChatWebSocketContext
39	{
40	  config: SheafChatConfig;
41	  agentManager: AgentManager;
42	  broadcasterRegistry: SessionBroadcasterRegistry;
43	}
44	
45	export interface ChatWebSocketConnectParams
46	{
47	  pile: string;
48	  sessionId: string;
49	  clientId?: string;
50	  after?: number;
51	}
52	
53	export function rejectUpgradeWithHttpStatus(
54	  socket: Duplex,
55	  statusCode: number,
56	  statusText: string,
57	): void
58	{
59	  const body = `${statusText}\r\n`;
60	  socket.write(
61	    `HTTP/1.1 ${statusCode} ${statusText}\r\n`
62	    + `Content-Type: text/plain\r\n`
63	    + `Content-Length: ${Buffer.byteLength(body)}\r\n`
64	    + `Connection: close\r\n`
65	    + `\r\n`
66	    + body,
67	  );
68	  socket.destroy();
69	}
70	
71	export function CreateChatWebSocketServer(): WebSocketServer
72	{
73	  return new WebSocketServer({ noServer: true });
74	}
75	
76	export function ParseChatWebSocketQuery(url: URL): ChatWebSocketConnectParams
77	{
78	  const pile = url.searchParams.get("p") ?? url.searchParams.get("pile");
79	
80	  if (pile === null || pile.length === 0)
81	  {
82	    throw new StorageError("invalid_request", "pile query parameter is required");
83	  }
84	
85	  const session = url.searchParams.get("session");
86	
87	  if (session === null || session.length === 0)
88	  {
89	    throw new StorageError("invalid_request", "session query parameter is required");
90	  }
91	
92	  const validatedPile = ValidatePileName(pile);
93	  const validatedSessionId = ValidateSessionId(session);
94	  const clientId = url.searchParams.get("client") ?? undefined;
95	  const after = ParseOptionalInteger(url.searchParams.get("after"), "after");
96	
97	  const params: ChatWebSocketConnectParams = {
98	    pile: validatedPile,
99	    sessionId: validatedSessionId,
100	  };
101	
102	  if (clientId !== undefined && clientId.length > 0)
103	  {
104	    params.clientId = clientId;
105	  }
106	
107	  if (after !== undefined)
108	  {
109	    params.after = after;
110	  }
111	
112	  return params;
113	}
114	
115	export function MatchChatWebSocketPath(pathname: string): boolean
116	{
117	  return pathname === "/ws/chat";
118	}
119	
120	async function SessionFileExists(
121	  context: ChatWebSocketContext,
122	  pile: string,
123	  sessionId: string,
124	): Promise<boolean>
125	{
126	  const sessionPath = ResolveSessionFilePath(context.agentManager.storagePaths, pile, sessionId);
127	
128	  try
129	  {
130	    await access(sessionPath);
131	    return true;
132	  }
133	  catch
134	  {
135	    return false;
136	  }
137	}
138	
139	export async function ValidateChatWebSocketConnect(
140	  context: ChatWebSocketContext,
141	  params: ChatWebSocketConnectParams,
142	): Promise<void>
143	{
144	  const exists = await SessionFileExists(context, params.pile, params.sessionId);
145	
146	  if (!exists)
147	  {
148	    throw new StorageError("not_found", "session not found");
149	  }
150	}
151	
152	function SendErrorFrame(
153	  socket: WebSocket,
154	  params: ChatWebSocketConnectParams,
155	  code: string,
156	  message: string,
157	  fatal = false,
158	  requestId?: string,
159	): void
160	{
161	  const payload: Record<string, unknown> = {
162	    code,
163	    message,
164	    fatal,
165	  };
166	
167	  if (requestId !== undefined)
168	  {
169	    payload.requestId = requestId;
170	  }
171	
172	  const envelope = CreateChatEnvelope({
173	    kind: x_serverErrorKind,
174	    pile: params.pile,
175	    sessionId: params.sessionId,
176	    clientId: params.clientId,
177	    payload,
178	  });
179	
180	  if (socket.readyState === WebSocket.OPEN)
181	  {
182	    socket.send(JSON.stringify(envelope));
183	  }
184	}
185	
186	async function SendHello(
187	  client: ConnectedClient,
188	  context: ChatWebSocketContext,
189	  params: ChatWebSocketConnectParams,
190	  broadcaster: Awaited<ReturnType<SessionBroadcasterRegistry["GetOrCreate"]>>,
191	  onAttached: () => void,
192	): Promise<void>
193	{
194	  const status = await context.agentManager.attachSession(
195	    params.pile,
196	    params.sessionId,
197	    client.connectionId,
198	  );
199	  onAttached();
200	
201	  const historyWindow = await broadcaster.HistoryWindow();
202	  const models = context.agentManager.listModels();
203	  const manifest = status.manifest;
204	
205	  const helloPayload: Record<string, unknown> = {
206	    connectionId: client.connectionId,
207	    manifest: manifest ?? null,
208	    latestSequence: historyWindow.newestSequence ?? 0,
209	    historyWindow,
210	    models,
211	    activeModel: status.model,
212	  };
213	
214	  if (manifest === undefined && status.provisionalRootDirectory !== undefined)
215	  {
216	    helloPayload.provisionalSession = {
217	      rootDirectory: RelativizeAbsolutePath(
218	        status.provisionalRootDirectory,
219	        context.config.repoRoot,
220	      ),
221	      model: status.model,
222	    };
223	  }
224	
225	  const envelope = CreateChatEnvelope({
226	    kind: x_serverHelloKind,
227	    pile: params.pile,
228	    sessionId: params.sessionId,
229	    clientId: params.clientId,
230	    payload: helloPayload,
231	  });
232	
233	  client.socket.send(JSON.stringify(envelope));
234	}
235	
236	async function SendReplayAndCaughtUp(
237	  client: ConnectedClient,
238	  params: ChatWebSocketConnectParams,
239	  broadcaster: Awaited<ReturnType<SessionBroadcasterRegistry["GetOrCreate"]>>,
240	  replayThroughSequence: number,
241	): Promise<void>
242	{
243	  if (params.after !== undefined)
244	  {
245	    await broadcaster.ReplayAfter(client, params.after, replayThroughSequence);
246	  }
247	
248	  const caughtUp = CreateChatEnvelope({
249	    kind: x_serverCaughtUpKind,
250	    pile: params.pile,
251	    sessionId: params.sessionId,
252	    clientId: params.clientId,
253	    payload: {},
254	  });
255	
256	  client.socket.send(JSON.stringify(caughtUp));
257	  await broadcaster.ReplayAfter(client, replayThroughSequence);
258	}
259	
260	export async function AttachChatWebSocketConnection(
261	  socket: WebSocket,
262	  params: ChatWebSocketConnectParams,
263	  context: ChatWebSocketContext,
264	): Promise<void>
265	{
266	  const key = {
267	    pile: params.pile,
268	    sessionId: params.sessionId,
269	  };
270	
271	  const broadcaster = await context.broadcasterRegistry.GetOrCreate({
272	    key,
273	    config: context.config,
274	    storagePaths: context.agentManager.storagePaths,
275	    agentManager: context.agentManager,
276	  });
277	
278	  const client = broadcaster.RegisterClient(socket, params.clientId);
279	  const replayThroughSequence = broadcaster.LatestSequence;
280	  let connectionEnded = false;
281	  let runtimeAttached = false;
282	  let runtimeDetached = false;
283	
284	  const cleanup = () =>
285	  {
286	    connectionEnded = true;
287	    broadcaster.RemoveClient(client.connectionId);
288	
289	    if (runtimeAttached && !runtimeDetached)
290	    {
291	      runtimeDetached = true;
292	      context.agentManager.markClientDetached(key, client.connectionId);
293	    }
294	
295	    context.broadcasterRegistry.ReleaseIfIdle(key);
296	  };
297	
298	  socket.on("close", cleanup);
299	
300	  try
301	  {
302	    await SendHello(client, context, params, broadcaster, () =>
303	    {
304	      runtimeAttached = true;
305	    });
306	
307	    if (connectionEnded || socket.readyState !== WebSocket.OPEN)
308	    {
309	      cleanup();
310	      return;
311	    }
312	
313	    await SendReplayAndCaughtUp(client, params, broadcaster, replayThroughSequence);
314	
315	    if (connectionEnded || socket.readyState !== WebSocket.OPEN)
316	    {
317	      cleanup();
318	      return;
319	    }
320	
321	    broadcaster.ActivateClient(client);
322	  }
323	  catch (error)
324	  {
325	    const message = error instanceof Error ? error.message : String(error);
326	    const code = error instanceof StorageError ? error.code : "connection_failed";
327	    SendErrorFrame(socket, params, code, message, true);
328	    socket.close();
329	    cleanup();
330	    return;
331	  }
332	
333	  socket.on("message", (data) =>
334	  {
335	    void HandleClientMessage(socket, client, params, context, broadcaster, data);
336	  });
337	
338	}
339	
340	async function HandleClientMessage(
341	  socket: WebSocket,
342	  client: ConnectedClient,
343	  params: ChatWebSocketConnectParams,
344	  context: ChatWebSocketContext,
345	  broadcaster: Awaited<ReturnType<SessionBroadcasterRegistry["GetOrCreate"]>>,
346	  data: WebSocket.RawData,
347	): Promise<void>
348	{
349	  let parsed: unknown;
350	
351	  try
352	  {
353	    parsed = JSON.parse(data.toString());
354	  }
355	  catch
356	  {
357	    SendErrorFrame(socket, params, "invalid_frame", "malformed JSON frame", false);
358	    return;
359	  }
360	
361	  let frame;
362	
363	  try
364	  {
365	    frame = ParseClientFrame(parsed);
366	  }
367	  catch (error)
368	  {
369	    const message = error instanceof Error ? error.message : String(error);
370	    const code = error instanceof StorageError ? error.code : "invalid_frame";
371	    SendErrorFrame(socket, params, code, message, false);
372	    return;
373	  }
374	
375	  if (frame.frame.pile !== params.pile || frame.frame.sessionId !== params.sessionId)
376	  {
377	    SendErrorFrame(
378	      socket,
379	      params,
380	      "invalid_frame",
381	      "frame pile/sessionId does not match connection",
382	      false,
383	      frame.frame.id,
384	    );
385	    return;
386	  }
387	
388	  const key = {
389	    pile: params.pile,
390	    sessionId: params.sessionId,
391	  };
392	
393	  try
394	  {
395	    switch (frame.kind)
396	    {
397	      case x_clientHelloKind:
398	        break;
399	
400	      case x_clientUserMessageKind:
401	        await broadcaster.HandleUserMessage(client.connectionId, frame.payload);
402	        break;
403	
404	      case x_clientHistoryRequestKind:
405	        await broadcaster.HandleHistoryRequest(
406	          client.connectionId,
407	          frame.frame.id,
408	          frame.payload,
409	        );
410	        break;
411	
412	      case x_clientModelSelectKind:
413	        await context.agentManager.selectModel(
414	          key,
415	          ToModelReference(frame.payload),
416	          frame.payload.applyTo ?? "next_turn",
417	        );
418	        break;
419	
420	      case x_clientAckKind:
421	        broadcaster.RecordAck(client.connectionId, frame.payload.sequence);
422	        break;
423	
424	      case x_clientCancelKind:
425	      case x_clientStopGeneratingKind:
426	        await context.agentManager.cancelTurn(key);
427	        break;
428	
429	      case x_clientPingKind:
430	      {
431	        const pong = CreateChatEnvelope({
432	          kind: x_serverPongKind,
433	          pile: params.pile,
434	          sessionId: params.sessionId,
435	          clientId: params.clientId,
436	          payload: {
437	            requestId: frame.frame.id,
438	          },
439	        });
440	        socket.send(JSON.stringify(pong));
441	        break;
442	      }
443	    }
444	  }
445	  catch (error)
446	  {
447	    const message = error instanceof Error ? error.message : String(error);
448	    const code = error instanceof StorageError ? error.code : "request_failed";
449	    SendErrorFrame(socket, params, code, message, false, frame.frame.id);
450	  }
451	}
452	
453	export async function ResolveChatWebSocketUpgrade(
454	  context: ChatWebSocketContext,
455	  request: IncomingMessage,
456	): Promise<ChatWebSocketConnectParams | null>
457	{
458	  const url = new URL(request.url ?? "/", `http://${request.headers.host ?? "localhost"}`);
459	
460	  if (!MatchChatWebSocketPath(url.pathname))
461	  {
462	    return null;
463	  }
464	
465	  try
466	  {
467	    const params = ParseChatWebSocketQuery(url);
468	    await ValidateChatWebSocketConnect(context, params);
469	    return params;
470	  }
471	  catch (error)
472	  {
473	    if (error instanceof StorageError)
474	    {
475	      throw error;
476	    }
477	
478	    throw new StorageError(
479	      "invalid_request",
480	      error instanceof Error ? error.message : String(error),
481	    );
482	  }
483	}
484	
485	export function StorageErrorToHttpStatus(error: StorageError): number
486	{
487	  switch (error.code)
488	  {
489	    case "not_found":
490	      return 404;
491	
492	    case "invalid_pile":
493	    case "invalid_session_id":
494	    case "invalid_request":
495	    case "invalid_history_request":
496	      return 400;
497	
498	    default:
499	      return 400;
500	  }
501	}
