650	export class SessionBroadcasterRegistry
651	{
652	  private readonly m_broadcasters = new Map<string, SessionBroadcaster>();
653	
654	  async GetOrCreate(options: SessionBroadcasterOptions): Promise<SessionBroadcaster>
655	  {
656	    const encodedKey = FormatSessionKey(options.key);
657	    let broadcaster = this.m_broadcasters.get(encodedKey);
658	
659	    if (broadcaster === undefined)
660	    {
661	      broadcaster = new SessionBroadcaster(options);
662	      await broadcaster.InitializeSequence();
663	      this.m_broadcasters.set(encodedKey, broadcaster);
664	    }
665	
666	    return broadcaster;
667	  }
668	
669	  Get(key: SessionKey): SessionBroadcaster | undefined
670	  {
671	    return this.m_broadcasters.get(FormatSessionKey(key));
672	  }
673	
674	  Remove(key: SessionKey): void
675	  {
676	    const encodedKey = FormatSessionKey(key);
677	    const broadcaster = this.m_broadcasters.get(encodedKey);
678	
679	    if (broadcaster !== undefined)
680	    {
681	      broadcaster.Dispose();
682	      this.m_broadcasters.delete(encodedKey);
683	    }
684	  }
685	
686	  ReleaseIfIdle(key: SessionKey): void
687	  {
688	    const broadcaster = this.Get(key);
689	
690	    if (broadcaster === undefined || broadcaster.ClientCount > 0)
691	    {
692	      return;
693	    }
694	
695	    this.Remove(key);
696	  }
697	
698	  Dispose(): void
699	  {
700	    for (const broadcaster of this.m_broadcasters.values())
701	    {
702	      broadcaster.Dispose();
703	    }
704	
705	    this.m_broadcasters.clear();
706	  }
707	}
